#!/usr/bin/env python3
"""unions-of-string-literals.py <seed> [<families>]: every family a union of 2 to 40 string literals OF ITS OWN (lengths 0 to 24, 8-bit and 16-bit, some that look like numbers, some that differ in the last letter alone, some shared with other families' unions), alone or with undefined | null | number beside it, held in every kind of place (a variable, a parameter, a result, a field of a record | of a class, optional, an element, a tuple, a Map's key and value, a Set, a closure, a module variable, a default, a rest), filled from literals, from STRINGS MADE AT RUN TIME that equal a literal (sliced, joined, out of char codes, a 16-bit buffer of Latin-1, JSON, templates), from narrowing a plain string, from another union that is wider | narrower | overlaps; and USED AS A STRING in every way: === !== == < >, switch (exhaustive and with default), typeof, length, charAt, [i], +, templates, toUpperCase, includes, localeCompare, as a key of a record | an object literal | a Map, `in`, JSON.stringify (alone, in a record, in a list), String(), Object.is, sort, join, spread into characters, for-of, RegExp.test, as an argument of untyped code that keeps it and hands it back. Garbage is made in between. Lines `F.. others` hand in what is no member (as plain or a throw); every other line as plain Bun's."""
import random, sys, json
seed = int(sys.argv[1]); count = int(sys.argv[2]) if len(sys.argv) > 2 else 14
R = random.Random(seed); J = lambda s: json.dumps(s, ensure_ascii=False)
POOL = ['', 'a', 'b', 'ab', 'ba', 'abc', 'abd', 'type', 'kind', 'left', 'right', 'center', 'start', 'end', 'open', 'closed', 'pending', 'fulfilled', 'rejected', 'GET', 'POST', 'get', '0', '1', '-1', '1.5', 'NaN', 'true', 'false', 'null', 'undefined', 'length', 'constructor', '__proto__', 'toString', 'é', '日本', 'naïve', 'a b', 'a-b', 'a_b', 'StringLiteral', 'NumericLiteral', 'TemplateLiteral', 'identifier', 'a very long literal indeed', 'a very long literal indeee']
print('''declare const console: { log(...values: unknown[]): void };
const attempt = (f: () => unknown): string => { try { const v = f(); return typeof v === "string" ? v : JSON.stringify(v) ?? String(v); } catch (e) { return "THROWS " + (e as Error).name; } };
const codes = (s: string): string => { let o = ""; for (let i = 0; i < s.length; i++) o += String.fromCharCode(s.charCodeAt(i)); return o; };
const made = (s: string, how: number): string => (how % 7 === 0 ? s : how % 7 === 1 ? ("x" + s).slice(1) : how % 7 === 2 ? s.split("").join("") : how % 7 === 3 ? codes(s) : how % 7 === 4 ? (s + "\\u65e5").slice(0, s.length) : how % 7 === 5 ? JSON.parse(JSON.stringify(s)) : `${s}`);
let sink: unknown[] = []; function churn(): void { sink = []; for (let i = 0; i < 300; i++) sink.push({ i, s: "g" + i }); sink = []; }
const kept: any[] = []; const keep = (v: any): any => { kept.push(v); return kept[kept.length - 1]; };''')
for f in range(count):
    ls = R.sample(POOL, R.choice([2, 2, 3, 4, 5, 8, 12, 24, 40])); U = ' | '.join(J(l) for l in ls); extra = R.choice(['', '', '', ' | undefined', ' | null', ' | number'])
    sub = ls[:max(1, len(ls) // 2)]
    print('type U%d = %s;' % (f, U)); print('type N%d = %s;' % (f, ' | '.join(J(l) for l in sub))); print('type E%d = U%d%s;' % (f, f, extra))
    print('const all%d: U%d[] = [%s];' % (f, f, ', '.join(J(l) for l in ls)))
    print('const is%d = (s: string): s is U%d => (all%d as string[]).includes(s);' % (f, f, f))
    print('type Rec%d = { tag: U%d; other?: E%d; n: number };' % (f, f, f)); print('class K%d { tag: U%d; list: U%d[] = []; opt?: U%d; constructor(tag: U%d) { this.tag = tag; } set(t: U%d): this { this.tag = t; this.list.push(t); return this; } }' % (f, f, f, f, f, f))
    print('let module%d: E%d = %s;' % (f, f, J(ls[0])))
    print('const table%d: Record<U%d, number> = { %s };' % (f, f, ', '.join('%s: %d' % ('[%s]' % J(l) if l == '__proto__' else J(l), i) for i, l in enumerate(ls))))
    sw = ' '.join('case %s: return %d;' % (J(l), i) for i, l in enumerate(ls))
    print('function index%d(u: U%d): number { switch (u) { %s } }' % (f, f, sw))
    print('function some%d(u: E%d): string { switch (u) { %s default: return "other " + String(u); } }' % (f, f, ' '.join('case %s: return "hit%d";' % (J(l), i) for i, l in enumerate(ls[:3]))))
    USES = ['u === %s' % J(ls[0]), 'u !== %s' % J(ls[-1]), 'u == %s' % J(ls[len(ls) // 2]), '(u < %s)' % J(ls[0]), '(u > (%s as string))' % J(ls[-1]), 'typeof u', 'u.length', 'u.charAt(0)', 'u[0]', 'u[u.length - 1]', 'u + "!"', '"<" + u + ">"', '`${u}|${u}`', 'u.toUpperCase()', 'u.includes("a")', 'u.localeCompare("b")', 'u.slice(1)', 'u.padStart(3, "*")', 'u.charCodeAt(0)', 'u.indexOf("e")', 'u.split("").length', '[...u].length', 'u.startsWith("a")', 'u.replace("a", "A")', 'u.concat(u)', 'u.at(-1)', 'u.trim() === u', 'u.normalize() === u', 'u.codePointAt(0)',
            'table%d[u]' % f, 'index%d(u)' % f, 'some%d(u)' % f, 'JSON.stringify(u)', 'JSON.stringify({ u })', 'JSON.stringify([u, u])', 'String(u)', 'Object.is(u, %s)' % J(ls[0]), '/^a/.test(u)', 'all%d.indexOf(u)' % f, 'all%d.includes(u)' % f, 'new Set(all%d).has(u)' % f, 'new Map(all%d.map((x, i) => [x, i])).get(u)' % f, '({ [u]: 1 })[u]', 'u in table%d' % f, 'Object.keys({ [u]: 1 })[0] === u', 'keep(u) === u', 'typeof keep(u)', '(keep({ u }).u as string).length', 'is%d(u)' % f, '[u, %s].sort().join()' % J(ls[0]), '(u as string) === made(u, 3)', 'Number(u)', 'Boolean(u)', '!u', 'u || "empty"', 'u ?? "nil"', 'encodeURIComponent(u)', 'Symbol.for(u).description', 'u.valueOf() === u', 'new String(u).length', 'Object(u) instanceof String', 'parseInt(u, 10)', '((x: string) => x.length)(u)', '((x: unknown) => typeof x)(u)', '((x: any) => x + 1)(u)']
    chosen = R.sample(USES, 16)
    print('function uses%d(u: U%d): string { return [%s].map(v => (typeof v === "string" ? v : String(v))).join("~"); }' % (f, f, ', '.join(chosen)))
    PLACES = ['((v: U%d) => v)(u)' % f, '(() => { const r: Rec%d = { tag: u, n: 1 }; churn(); return r.tag; })()' % f, '(() => { const r: Rec%d = { tag: %s, other: u, n: 1 }; churn(); return r.other as U%d; })()' % (f, J(ls[0]), f), 'new K%d(u).tag' % f, 'new K%d(%s).set(u).tag' % (f, J(ls[0])), 'new K%d(%s).set(u).list[0]!' % (f, J(ls[0])), '(() => { const k = new K%d(%s); k.opt = u; churn(); return k.opt!; })()' % (f, J(ls[0])),
              '[u][0]!', '([%s, u] as U%d[]).pop()!' % (J(ls[0]), f), '(() => { const t: [number, U%d] = [1, u]; return t[1]; })()' % f, 'new Map<number, U%d>([[1, u]]).get(1)!' % f, '[...new Set<U%d>([u])][0]!' % f, '[...new Map<U%d, number>([[u, 1]]).keys()][0]!' % f, '(() => { const g = () => u; churn(); return g(); })()', '(() => { module%d = u; churn(); return module%d as U%d; })()' % (f, f, f), '((v: U%d = %s) => v)(u)' % (f, J(ls[0])), '((...vs: U%d[]) => vs[0]!)(u)' % f, '(({ tag }: Rec%d) => tag)({ tag: u, n: 0 })' % f, '({ ...{ tag: u, n: 1 } as Rec%d }).tag' % f, '(JSON.parse(JSON.stringify({ tag: u, n: 1 })) as Rec%d).tag' % f, '(keep(u) as U%d)' % f, '(function* (): Generator<U%d> { yield u; })().next().value as U%d' % (f, f), '(u as E%d) as U%d' % (f, f), '((v: string): U%d => (is%d(v) ? v : %s))(u)' % (f, f, J(ls[0])), '((v: N%d | U%d): U%d => v)(u)' % (f, f, f)]
    places = R.sample(PLACES, 9)
    print('function through%d(u: U%d): string { return [%s].map(v => uses%d(v)).filter((s, i, a) => s !== a[0]).length + ":" + uses%d(u); }' % (f, f, ', '.join(places), f, f))
    print('{ for (let i = 0; i < 150; i++) through%d(all%d[i %% all%d.length]!); const out: string[] = []; for (const l of all%d) for (let how = 0; how < 7; how++) { const s = made(l, how); out.push(attempt(() => (is%d(s) ? through%d(s) : "no member"))); } console.log("F%d: " + out.filter((s, i) => i %% 7 === 0 || s !== out[i - (i %% 7)]).join(" || ")); console.log("F%d others: " + ["zzz", "A", " ", "a\\0", %s + "x"].map(s => attempt(() => (is%d(s) ? "member" : some%d(s as never)))).join(" | ") + " " + attempt(() => some%d(module%d))); }' % (f, f, f, f, f, f, f, f, J(ls[0]), f, f, f, f))
